BEGIN;
-- 1. POSTULANTE
CREATE TABLE POSTULANTE (
    id_postulante INT NOT NULL,
    ci_pasaporte VARCHAR(20) NOT NULL,
    tipo_postulante VARCHAR(50),
    nombres VARCHAR(100) NOT NULL,
    paterno VARCHAR(100),
    materno VARCHAR(100),
    email VARCHAR(150),
    telefono VARCHAR(20),
    CONSTRAINT PK_POSTULANTE PRIMARY KEY (id_postulante)
);

-- 2. FACULTAD
CREATE TABLE FACULTAD (
    id_facultad INT NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    CONSTRAINT PK_FACULTAD PRIMARY KEY (id_facultad)
);

-- 3. CARRERA
CREATE TABLE CARRERA (
    id_carrera INT NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    id_facultad INT NOT NULL,
    CONSTRAINT PK_CARRERA PRIMARY KEY (id_carrera),
    CONSTRAINT FK_CARRERA_FACULTAD FOREIGN KEY (id_facultad) 
        REFERENCES FACULTAD(id_facultad) ON DELETE CASCADE
);

-- 4. MATERIA
CREATE TABLE MATERIA (
    id_materia INT NOT NULL,
    nombre VARCHAR(100) NOT NULL,
    CONSTRAINT PK_MATERIA PRIMARY KEY (id_materia)
);

-- 5. CONTIENE
CREATE TABLE CONTIENE (
    id_carrera INT NOT NULL,
    id_materia INT NOT NULL,
    CONSTRAINT PK_CONTIENE PRIMARY KEY (id_carrera, id_materia),
    CONSTRAINT FK_CONTIENE_CARRERA FOREIGN KEY (id_carrera) 
        REFERENCES CARRERA(id_carrera) ON DELETE CASCADE,
    CONSTRAINT FK_CONTIENE_MATERIA FOREIGN KEY (id_materia) 
        REFERENCES MATERIA(id_materia) ON DELETE CASCADE
);

-- 6. CONVOCATORIA
CREATE TABLE CONVOCATORIA (
    id_convocatoria INT NOT NULL,
    gestion VARCHAR(20) NOT NULL,
    modalidad VARCHAR(50),
    costo_nac NUMERIC(10, 2),
    costo_ext NUMERIC(10, 2),
    fecha_inicio_pago DATE,
    fecha_fin_pago DATE,
    id_carrera INT NOT NULL,
    CONSTRAINT PK_CONVOCATORIA PRIMARY KEY (id_convocatoria),
    CONSTRAINT FK_CONVOCATORIA_CARRERA FOREIGN KEY (id_carrera) 
        REFERENCES CARRERA(id_carrera) ON DELETE CASCADE
);

-- 7. INSCRIPCION
CREATE TABLE INSCRIPCION (
    id_inscripcion INT NOT NULL,
    fecha_inscripcion DATE NOT NULL,
    monto_pagado NUMERIC(10, 2),
    estado_inscripcion VARCHAR(50),
    id_postulante INT NOT NULL,
    id_convocatoria INT NOT NULL,
    CONSTRAINT PK_INSCRIPCION PRIMARY KEY (id_inscripcion),
    CONSTRAINT FK_INSCRIPCION_POSTULANTE FOREIGN KEY (id_postulante) 
        REFERENCES POSTULANTE(id_postulante) ON DELETE CASCADE,
    CONSTRAINT FK_INSCRIPCION_CONVOCATORIA FOREIGN KEY (id_convocatoria) 
        REFERENCES CONVOCATORIA(id_convocatoria) ON DELETE CASCADE
);
-- 8. PREGUNTA
CREATE TABLE PREGUNTA (
    id_materia INT NOT NULL,
    nro_pregunta INT NOT NULL,
    enunciado TEXT NOT NULL,
    opcion_correcta VARCHAR(10),
    puntaje NUMERIC(5, 2),
    CONSTRAINT PK_PREGUNTA PRIMARY KEY (id_materia, nro_pregunta),
    CONSTRAINT FK_PREGUNTA_MATERIA FOREIGN KEY (id_materia) 
        REFERENCES MATERIA(id_materia) ON DELETE CASCADE
);

-- 9. OPCION
CREATE TABLE OPCION (
    id_materia INT NOT NULL,
    nro_pregunta INT NOT NULL,
    id_opcion VARCHAR(10) NOT NULL,
    descripcion TEXT NOT NULL,
    CONSTRAINT PK_OPCION PRIMARY KEY (id_materia, nro_pregunta, id_opcion),
    CONSTRAINT FK_OPCION_PREGUNTA FOREIGN KEY (id_materia, nro_pregunta) 
        REFERENCES PREGUNTA(id_materia, nro_pregunta) ON DELETE CASCADE
);

-- 10. RESPUESTA
CREATE TABLE RESPUESTA (
    id_materia INT NOT NULL,
    id_pregunta INT NOT NULL,
    id_inscripcion INT NOT NULL,
    opcion VARCHAR(10) NOT NULL,
    CONSTRAINT PK_RESPUESTA PRIMARY KEY (id_inscripcion, id_materia, id_pregunta),
    CONSTRAINT FK_RESPUESTA_INSCRIPCION FOREIGN KEY (id_inscripcion) 
        REFERENCES INSCRIPCION(id_inscripcion) ON DELETE CASCADE,
    CONSTRAINT FK_RESPUESTA_PREGUNTA FOREIGN KEY (id_materia, id_pregunta) 
        REFERENCES PREGUNTA(id_materia, nro_pregunta) ON DELETE CASCADE
);

